style.css:
@-moz-document domain("fanfiction.net"), domain("m.fanfiction.net"), domain("fictionpress.com"), domain("m.fictionpress.com") {
/* ---- Palette ---------------------------------------------------------- */
  :root {
    color-scheme: dark;
    --ff-bg: #14181d;
    --ff-surface: #1c2128;
    --ff-surface-2: #1a1f26;
    --ff-header: #0d1117;
    --ff-border: #262c33;
    --ff-border-2: #2d333b;
    --ff-text: #e6edf3;
    --ff-body: #c4cdd6;
    --ff-muted: #9aa5b1;
    --ff-link: #5fb0e6;
    --ff-link-hover: #9bd4ff;
    --ff-green: #3fb950;
    /* brand accents refined for dark: FFN navy → readable blue-slate; FP maroon handled below */
    --ff-brand: #243b66;
  }

  /* ---- Base ------------------------------------------------------------- */
  html, body {
    background: var(--ff-bg) !important;
    color: var(--ff-body) !important;
  }

  /* Soften every light border into a subtle dark line */
  * {
    border-color: var(--ff-border) !important;
  }

  /* ---- Main content surfaces ------------------------------------------- */
  #content_wrapper,
  #content_wrapper_inner,
  #content_parent,
  .zui,
  .panel_normal,
  .lc,
  .lc-wrapper,
  .lc-lg,
  .lc-md,
  .lc-sm,
  .gui_normal,
  .gui_table,
  .goog-rtopics,
  .table-striped,
  .zmenu {
    background-color: var(--ff-surface) !important;
    color: var(--ff-body) !important;
  }

  #content_wrapper {
    box-shadow: none !important;
  }

  /* keep nested transparent wrappers transparent so we don't stack surfaces */
  .lc-wrapper,
  #content_wrapper_inner,
  #content_parent {
    background-color: transparent !important;
  }

  /* ---- Header / top brand bar ------------------------------------------ */
  /* FFN navy + FP maroon raw bars refined to harmonize with the dark palette */
  #top {
    background-color: var(--ff-header) !important;
    border-bottom: 1px solid var(--ff-border-2) !important;
  }
  /* Mobile (m.fanfiction.net / m.fictionpress.com) top nav bar paints a
     white→grey linear-gradient background-image (bg-color transparent) — the
     already-light nav labels sit invisibly on it, and the bg-color audit is
     blind to the gradient. Kill the gradient, give it the dark header bg. */
  .t_head {
    background-image: none !important;
    background-color: var(--ff-header) !important;
    border-bottom: 1px solid var(--ff-border-2) !important;
  }
  #top a,
  #top .icon-fictionpress,
  #name_login,
  #name_login a {
    color: var(--ff-text) !important;
  }
  /* Login / Sign Up pills in the header keep an accent so they stand out */
  #top .btn,
  #name_login .btn {
    background-color: var(--ff-brand) !important;
    color: var(--ff-text) !important;
    border-color: var(--ff-border-2) !important;
  }
  #top .btn:hover,
  #name_login .btn:hover {
    background-color: #2d4a80 !important;
  }

  /* ---- Navigation menus / dropdowns ------------------------------------ */
  #nav_internal,
  #nav_internal a,
  .menulink,
  .xmenu_item,
  .dropdown,
  .dropdown > a,
  .dropdown-toggle {
    color: var(--ff-text) !important;
  }

  .dropdown-menu,
  ul.dropdown-menu,
  .open > .dropdown-menu {
    background-color: var(--ff-surface) !important;
    border: 1px solid var(--ff-border-2) !important;
    box-shadow: 0 6px 18px rgba(0,0,0,.5) !important;
  }
  .dropdown-menu li > a,
  .dropdown-menu a {
    color: var(--ff-body) !important;
  }
  .dropdown-menu li > a:hover,
  .dropdown-menu a:hover,
  .dropdown-menu > .active > a {
    background-color: var(--ff-surface-2) !important;
    color: var(--ff-text) !important;
  }

  /* sub-nav grey links (Stories / Crossovers / All / Specific) */
  .menulink,
  #content_wrapper a[style*="color:#999"],
  .menulink a {
    color: var(--ff-muted) !important;
  }

  /* ---- Links ------------------------------------------------------------ */
  a {
    color: var(--ff-link) !important;
  }
  a:hover {
    color: var(--ff-link-hover) !important;
  }
  /* keep header / nav links from inheriting the body link blue where set above */
  #top a:hover {
    color: var(--ff-link-hover) !important;
  }

  /* ---- Headings & general text ----------------------------------------- */
  h1, h2, h3, h4, h5, h6, b, strong {
    color: var(--ff-text) !important;
  }
  .xcontrast_txt,
  .xgray,
  td, th, p, span, div, li, label, dt, dd {
    color: var(--ff-body) !important;
  }
  .xgray, .gray, small {
    color: var(--ff-muted) !important;
  }

  /* ---- Story list rows (browse / search results) ----------------------- */
  .z-list,
  .z-list-content {
    background-color: var(--ff-surface) !important;
    border-bottom: 1px solid var(--ff-border) !important;
  }
  .z-list:hover {
    background-color: var(--ff-surface-2) !important;
  }
  .z-list a,
  .z-list .stitle {
    color: var(--ff-link) !important;
  }
  .z-list .xgray,
  .z-list .z-padtop2 {
    color: var(--ff-body) !important;
  }

  /* ---- Story reader (#storytext core long-text surface) ---------------- */
  #storytext,
  #storytextp,
  .storytext {
    color: var(--ff-body) !important;
    background-color: transparent !important;
  }
  /* do NOT force a single color on inner runs — preserve author bold/italic/
     alignment/hr emphasis; only normalize the common black text default */
  #storytext p,
  #storytext div,
  #storytext span[style*="color: rgb(0, 0, 0)"],
  #storytext font[color="#000000"],
  #storytext font[color="black"] {
    color: var(--ff-body) !important;
  }
  #storytext hr {
    border-color: var(--ff-border-2) !important;
  }

  /* story info box on the chapter page */
  #profile_top {
    background-color: var(--ff-surface) !important;
    border: 1px solid var(--ff-border) !important;
    color: var(--ff-body) !important;
  }
  #profile_top b,
  #profile_top .xcontrast_txt {
    color: var(--ff-text) !important;
  }

  /* ---- Reading-options bar + chapter select ---------------------------- */
  select,
  select[name="chapter"],
  #chap_select {
    background-color: var(--ff-surface-2) !important;
    color: var(--ff-text) !important;
    border: 1px solid var(--ff-border-2) !important;
  }
  select option {
    background-color: var(--ff-surface-2) !important;
    color: var(--ff-text) !important;
  }

  /* ---- Browse filter bar buttons / segmented controls / sort tabs ------ */
  button,
  .btn,
  input[type="button"],
  input[type="submit"],
  input[type="reset"] {
    background-color: var(--ff-surface-2) !important;
    color: var(--ff-text) !important;
    border: 1px solid var(--ff-border-2) !important;
    background-image: none !important;
    text-shadow: none !important;
  }
  button:hover,
  .btn:hover {
    background-color: #232a32 !important;
    color: var(--ff-text) !important;
  }
  .btn.active,
  .btn-primary,
  .active > .btn {
    background-color: var(--ff-brand) !important;
    color: var(--ff-text) !important;
  }

  /* ---- Form inputs & search -------------------------------------------- */
  input[type="text"],
  input[type="search"],
  input[type="email"],
  input[type="password"],
  input:not([type]),
  textarea {
    background-color: var(--ff-surface-2) !important;
    color: var(--ff-text) !important;
    border: 1px solid var(--ff-border-2) !important;
  }
  ::placeholder {
    color: var(--ff-muted) !important;
    opacity: 1 !important;
  }

  /* ---- Tables (gui_table, forum topic lists, .table-striped) ----------- */
  /* FFN forums render rows as a striped table whose <td> carry their own
     light bg (rgb(249,249,249)); target the cells directly, not just rows. */
  .gui_table,
  .gui_table td,
  .gui_table th,
  .tcat,
  table.table,
  table.table td,
  table.table th,
  .table-striped td,
  .table-striped th,
  .table-striped > tbody > tr:nth-of-type(odd) > td,
  .table-bordered {
    background-color: var(--ff-surface) !important;
    color: var(--ff-body) !important;
    border-color: var(--ff-border) !important;
  }
  .tcat,
  thead th {
    background-color: var(--ff-header) !important;
    color: var(--ff-text) !important;
  }
  .table-striped > tbody > tr:nth-of-type(even) > td {
    background-color: var(--ff-surface-2) !important;
  }
  tr:hover > td {
    background-color: var(--ff-surface-2) !important;
  }

  /* ---- Forum post quotes ----------------------------------------------- */
  /* FFN styles quoted text with color:#535353 — readable on the old light
     posts, dark-on-dark here. Lift to body text, keep the quote accent bar. */
  blockquote,
  blockquote.quoteStyle,
  .quoteStyle {
    color: var(--ff-body) !important;
    border-color: var(--ff-border-2) !important;
  }

  /* ---- Badges / counters ----------------------------------------------- */
  /* default grey badge → dark chip with readable light text */
  .badge {
    background-color: var(--ff-surface-2) !important;
    color: var(--ff-text) !important;
    border: 1px solid var(--ff-border-2) !important;
    text-shadow: none !important;
  }
  .badge-blue {
    background-color: var(--ff-brand) !important;
    color: var(--ff-text) !important;
  }

  /* ---- Profile / story tabs (Bootstrap .nav-tabs) ---------------------- */
  /* FFN renders the active tab (li.active > a.current) with a white "folder"
     bg meant to sit on light content — paints a bright panel on dark. As a
     short 38px pill it slips past the height-based light-surface audit. */
  .nav-tabs > li > a,
  .nav-tabs a {
    background-color: transparent !important;
    color: var(--ff-link) !important;
  }
  .nav-tabs > li.active > a,
  .nav-tabs > .active > a:hover,
  .nav-tabs > .active > a:focus,
  .nav-tabs a.current {
    background-color: var(--ff-surface) !important;
    color: var(--ff-text) !important;
    border-color: var(--ff-border-2) !important;
    border-bottom-color: var(--ff-surface) !important;
  }
  .nav-tabs > li > a:hover {
    background-color: var(--ff-surface-2) !important;
  }

  /* ---- Advanced-filter modal ------------------------------------------- */
  .modal,
  .modal-body,
  .modal-header,
  .modal-footer,
  .modal-content,
  #filters {
    background-color: var(--ff-surface) !important;
    color: var(--ff-body) !important;
    border-color: var(--ff-border-2) !important;
  }
  .modal-backdrop { background-color: rgba(0,0,0,.6) !important; }

  /* ---- Semantic cues: keep status / completed green readable ----------- */
  /* FFN uses dark greens (e.g. #04761c "Complete"/"Plus") that vanish on
     dark; lift them to the palette green while keeping the semantic. */
  span[style*="color:green"],
  span[style*="#04761c"],
  span[style*="#080"],
  .status_complete,
  font[color="green"] {
    color: var(--ff-green) !important;
  }

  /* ---- Footer ----------------------------------------------------------- */
  #footer,
  .footer,
  #zfooter {
    background-color: var(--ff-header) !important;
    color: var(--ff-muted) !important;
    border-top: 1px solid var(--ff-border-2) !important;
  }
  #footer a, .footer a { color: var(--ff-link) !important; }

  /* ---- Ad slots: darken blank bright rectangles ------------------------ */
  ins.adsbygoogle,
  .adsbygoogle,
  div[id^="div-gpt-ad"],
  div[id*="_ad_"],
  div[id^="ad_"],
  .ad_slot,
  [id^="google_ads"],
  iframe[id^="google_ads"],
  iframe[id^="aswift"],
  .goog-rtopics,
  .goog-rentries,
  .goog-rentry,
  .google-anno,
  .google-anno-skip,
  .google-anno-sc {
    background-color: var(--ff-bg) !important;
  }

  /* ---- Misc: don't tint cover images ----------------------------------- */
  img, .cimage {
    background-color: transparent !important;
  }
}
